     "code": "import json\nfrom datetime import datetime\n\nclass EventStore:\n    def __init__(self):\n        self.events = []\n    \n    def append(self, aggregate_id, event_type, data):\n        event = {\n            \"id\": len(self.events) + 1,\n            \"aggregate_id\": aggregate_id,\n            \"type\": event_type,\n            \"data\": data,\n            \"timestamp\": datetime.now().isoformat()\n        }\n        self.events.append(event)\n        return event\n    \n    def get_events(self, aggregate_id):\n        return [e for e in self.events if e[\"aggregate_id\"] == aggregate_id]\n\nclass BankAccount:\n    def __init__(self, account_id, store: EventStore):\n        self.id = account_id\n        self.store = store\n        self.balance = 0\n    \n    def deposit(self, amount):\n        self.store.append(self.id, \"DEPOSITED\", {\"amount\": amount})\n        self.balance += amount\n    \n    def withdraw(self, amount):\n        if amount > self.balance:\n            raise ValueError(\"Insufficient funds\")\n        self.store.append(self.id, \"WITHDRAWN\", {\"amount\": amount})\n        self.balance -= amount\n    \n    def rebuild(self):\n        \"\"\"Rebuild state from events.\"\"\"\n        self.balance = 0\n        for event in self.store.get_events(self.id):\n            if event[\"type\"] == \"DEPOSITED\":\n                self.balance += event[\"data\"][\"amount\"]\n            elif event[\"type\"] == \"WITHDRAWN\":\n                self.balance -= event[\"data\"][\"amount\"]\n        return self.balance\n\nstore = EventStore()\naccount = BankAccount(\"ACC-001\", store)\naccount.deposit(1000)\naccount.deposit(500)\naccount.withdraw(200)\nprint(f\"Balance: {account.balance}\")  # 1300\n\n# Rebuild from events\naccount2 = BankAccount(\"ACC-001\", store)\nrebuilt_balance = account2.rebuild()\nprint(f\"Rebuilt balance: {rebuilt_balance}\")  # 1300\n\nprint(f\"\\nEvent log:\")\nfor e in store.get_events(\"ACC-001\"):\n    print(f\"  {e['type']}: {e['data']}\")",
