     "code": "from abc import ABC, abstractmethod\n\nclass Button(ABC):\n    @abstractmethod\n    def render(self): pass\n\nclass TextInput(ABC):\n    @abstractmethod\n    def render(self): pass\n\nclass LightButton(Button):\n    def render(self): return \"[Light Button]\"\n\nclass DarkButton(Button):\n    def render(self): return \"[Dark Button]\"\n\nclass LightTextInput(TextInput):\n    def render(self): return \"[Light Input ___]\"\n\nclass DarkTextInput(TextInput):\n    def render(self): return \"[Dark Input ___]\"\n\nclass UIFactory(ABC):\n    @abstractmethod\n    def create_button(self) -> Button: pass\n    @abstractmethod\n    def create_input(self) -> TextInput: pass\n\nclass LightThemeFactory(UIFactory):\n    def create_button(self): return LightButton()\n    def create_input(self): return LightTextInput()\n\nclass DarkThemeFactory(UIFactory):\n    def create_button(self): return DarkButton()\n    def create_input(self): return DarkTextInput()\n\ndef build_ui(factory: UIFactory):\n    button = factory.create_button()\n    text_input = factory.create_input()\n    print(f\"  {button.render()} {text_input.render()}\")\n\nprint(\"Light theme:\"); build_ui(LightThemeFactory())\nprint(\"Dark theme:\"); build_ui(DarkThemeFactory())",
