     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass EventEmitter:\n    def __init__(self):\n        self._listeners = {}\n    \n    def on(self, event, callback):\n        self._listeners.setdefault(event, []).append(callback)\n        return self\n    \n    def off(self, event, callback):\n        if event in self._listeners:\n            self._listeners[event].remove(callback)\n    \n    def emit(self, event, *args, **kwargs):\n        for callback in self._listeners.get(event, []):\n            callback(*args, **kwargs)\n\nclass OrderSystem(EventEmitter):\n    def place_order(self, order):\n        print(f\"Order placed: {order['id']}\")\n        self.emit(\"order_placed\", order)\n    \n    def cancel_order(self, order_id):\n        print(f\"Order cancelled: {order_id}\")\n        self.emit(\"order_cancelled\", order_id)\n\nsystem = OrderSystem()\nsystem.on(\"order_placed\", lambda o: print(f\"  [Email] Order {o['id']} confirmation sent\"))\nsystem.on(\"order_placed\", lambda o: print(f\"  [Inventory] Reserved items for order {o['id']}\"))\nsystem.on(\"order_placed\", lambda o: print(f\"  [Analytics] Tracked order {o['id']}\"))\nsystem.on(\"order_cancelled\", lambda id: print(f\"  [Refund] Processing refund for {id}\"))\n\nsystem.place_order({\"id\": \"ORD-001\", \"total\": 99.99})\nsystem.cancel_order(\"ORD-001\")",
