     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass PricingStrategy(ABC):\n    @abstractmethod\n    def calculate(self, base_price): pass\n\nclass RegularPricing(PricingStrategy):\n    def calculate(self, base_price):\n        return base_price\n\nclass PremiumPricing(PricingStrategy):\n    def calculate(self, base_price):\n        return base_price * 0.9  # 10% discount\n\nclass BlackFridayPricing(PricingStrategy):\n    def calculate(self, base_price):\n        return base_price * 0.5  # 50% off\n\nclass BulkPricing(PricingStrategy):\n    def __init__(self, quantity):\n        self.quantity = quantity\n    \n    def calculate(self, base_price):\n        if self.quantity >= 100: return base_price * 0.7\n        if self.quantity >= 50: return base_price * 0.8\n        if self.quantity >= 10: return base_price * 0.9\n        return base_price\n\nclass PriceCalculator:\n    def __init__(self, strategy: PricingStrategy):\n        self.strategy = strategy\n    \n    def get_price(self, base_price):\n        return round(self.strategy.calculate(base_price), 2)\n\nbase = 100.0\nfor name, strategy in [(\"Regular\", RegularPricing()), (\"Premium\", PremiumPricing()),\n                        (\"BlackFriday\", BlackFridayPricing()), (\"Bulk(50)\", BulkPricing(50))]:\n    calc = PriceCalculator(strategy)\n    print(f\"  {name}: ${calc.get_price(base)}\")",
