     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass TextProcessor(ABC):\n    @abstractmethod\n    def process(self, text): pass\n\nclass PlainText(TextProcessor):\n    def process(self, text):\n        return text\n\nclass UpperCaseDecorator(TextProcessor):\n    def __init__(self, wrapped):\n        self.wrapped = wrapped\n    def process(self, text):\n        return self.wrapped.process(text).upper()\n\nclass TrimDecorator(TextProcessor):\n    def __init__(self, wrapped):\n        self.wrapped = wrapped\n    def process(self, text):\n        return self.wrapped.process(text).strip()\n\nclass CensorDecorator(TextProcessor):\n    def __init__(self, wrapped, words):\n        self.wrapped = wrapped\n        self.words = words\n    def process(self, text):\n        result = self.wrapped.process(text)\n        for word in self.words:\n            result = result.replace(word, \"*\" * len(word))\n        return result\n\n# Stack decorators\nprocessor = CensorDecorator(\n    UpperCaseDecorator(\n        TrimDecorator(PlainText())\n    ),\n    words=[\"BAD\", \"UGLY\"]\n)\n\nprint(processor.process(\"  this is bad and ugly  \"))\n# Output: THIS IS *** AND ****",
