     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass Command(ABC):\n    @abstractmethod\n    def execute(self): pass\n    @abstractmethod\n    def undo(self): pass\n\nclass TextEditor:\n    def __init__(self):\n        self.content = \"\"\n    def __str__(self):\n        return self.content\n\nclass InsertCommand(Command):\n    def __init__(self, editor, text, position):\n        self.editor = editor\n        self.text = text\n        self.position = position\n    \n    def execute(self):\n        self.editor.content = (self.editor.content[:self.position] +\n                               self.text + self.editor.content[self.position:])\n    \n    def undo(self):\n        self.editor.content = (self.editor.content[:self.position] +\n                               self.editor.content[self.position + len(self.text):])\n\nclass DeleteCommand(Command):\n    def __init__(self, editor, position, length):\n        self.editor = editor\n        self.position = position\n        self.length = length\n        self.deleted = \"\"\n    \n    def execute(self):\n        self.deleted = self.editor.content[self.position:self.position + self.length]\n        self.editor.content = (self.editor.content[:self.position] +\n                               self.editor.content[self.position + self.length:])\n    \n    def undo(self):\n        self.editor.content = (self.editor.content[:self.position] +\n                               self.deleted + self.editor.content[self.position:])\n\nclass CommandHistory:\n    def __init__(self):\n        self.history = []\n    \n    def execute(self, command):\n        command.execute()\n        self.history.append(command)\n    \n    def undo(self):\n        if self.history:\n            self.history.pop().undo()\n\neditor = TextEditor()\nhistory = CommandHistory()\n\nhistory.execute(InsertCommand(editor, \"Hello World\", 0))\nprint(f\"After insert: '{editor}'\")     # Hello World\nhistory.execute(InsertCommand(editor, \" Beautiful\", 5))\nprint(f\"After insert: '{editor}'\")     # Hello Beautiful World\nhistory.execute(DeleteCommand(editor, 6, 9))\nprint(f\"After delete: '{editor}'\")     # Hello  World\nhistory.undo()\nprint(f\"After undo: '{editor}'\")       # Hello Beautiful World\nhistory.undo()\nprint(f\"After undo: '{editor}'\")       # Hello World",
