     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass DataPipeline(ABC):\n    def run(self, source):\n        data = self.extract(source)\n        validated = self.validate(data)\n        transformed = self.transform(validated)\n        self.load(transformed)\n        print(f\"Pipeline complete: {len(transformed)} records\")\n    \n    @abstractmethod\n    def extract(self, source): pass\n    \n    def validate(self, data):\n        return [d for d in data if d is not None]\n    \n    @abstractmethod\n    def transform(self, data): pass\n    \n    @abstractmethod\n    def load(self, data): pass\n\nclass CSVPipeline(DataPipeline):\n    def extract(self, source):\n        print(f\"Extracting from CSV: {source}\")\n        return [{\"name\": \"Alice\", \"age\": \"30\"}, {\"name\": \"Bob\", \"age\": \"25\"}, None]\n    \n    def transform(self, data):\n        return [{\"name\": d[\"name\"].upper(), \"age\": int(d[\"age\"])} for d in data]\n    \n    def load(self, data):\n        print(f\"Loading {len(data)} records to database\")\n\nclass APIPipeline(DataPipeline):\n    def extract(self, source):\n        print(f\"Fetching from API: {source}\")\n        return [{\"id\": 1, \"value\": 100}, {\"id\": 2, \"value\": 200}]\n    \n    def transform(self, data):\n        return [{\"id\": d[\"id\"], \"value_usd\": d[\"value\"] / 100} for d in data]\n    \n    def load(self, data):\n        print(f\"Sending {len(data)} records to warehouse\")\n\nCSVPipeline().run(\"data.csv\")\nAPIPipeline().run(\"https://api.example.com/data\")",
