     "t": "code",
     "lang": "python",
     "code": "class CharacterStyle:\n    _cache = {}\n    \n    def __new__(cls, font, size, color):\n        key = (font, size, color)\n        if key not in cls._cache:\n            instance = super().__new__(cls)\n            instance.font = font\n            instance.size = size\n            instance.color = color\n            cls._cache[key] = instance\n        return cls._cache[key]\n    \n    def __repr__(self):\n        return f\"Style({self.font}, {self.size}, {self.color})\"\n\nclass Character:\n    def __init__(self, char, style):\n        self.char = char\n        self.style = style  # Shared flyweight\n    \n    def render(self):\n        return f\"'{self.char}' [{self.style}]\"\n\n# Many characters share few styles\nstyle1 = CharacterStyle(\"Arial\", 12, \"black\")\nstyle2 = CharacterStyle(\"Arial\", 12, \"black\")  # Same object\nstyle3 = CharacterStyle(\"Bold\", 14, \"red\")\n\nprint(f\"Same style object: {style1 is style2}\")  # True\n\ntext = \"Hello\"\nchars = [Character(c, style1 if c.islower() else style3) for c in text]\nfor ch in chars:\n    print(f\"  {ch.render()}\")\n\nprint(f\"Unique style objects: {len(CharacterStyle._cache)}\")",
