     "code": "from abc import ABC, abstractmethod\n\nclass FileSystemItem(ABC):\n    def __init__(self, name):\n        self.name = name\n    \n    @abstractmethod\n    def get_size(self): pass\n    \n    @abstractmethod\n    def display(self, indent=0): pass\n\nclass File(FileSystemItem):\n    def __init__(self, name, size):\n        super().__init__(name)\n        self.size = size\n    \n    def get_size(self):\n        return self.size\n    \n    def display(self, indent=0):\n        print(f\"{'  ' * indent}📄 {self.name} ({self.size} KB)\")\n\nclass Directory(FileSystemItem):\n    def __init__(self, name):\n        super().__init__(name)\n        self.children = []\n    \n    def add(self, item):\n        self.children.append(item)\n        return self\n    \n    def get_size(self):\n        return sum(child.get_size() for child in self.children)\n    \n    def display(self, indent=0):\n        print(f\"{'  ' * indent}📁 {self.name} ({self.get_size()} KB)\")\n        for child in self.children:\n            child.display(indent + 1)\n\nroot = Directory(\"project\")\nsrc = Directory(\"src\")\nsrc.add(File(\"main.py\", 10)).add(File(\"utils.py\", 5)).add(File(\"models.py\", 15))\ntests = Directory(\"tests\")\ntests.add(File(\"test_main.py\", 8))\nroot.add(src).add(tests).add(File(\"README.md\", 2))\n\nroot.display()\nprint(f\"\\nTotal size: {root.get_size()} KB\")",
