     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass Shape(ABC):\n    @abstractmethod\n    def accept(self, visitor): pass\n\nclass Circle(Shape):\n    def __init__(self, radius):\n        self.radius = radius\n    def accept(self, visitor):\n        return visitor.visit_circle(self)\n\nclass Rectangle(Shape):\n    def __init__(self, width, height):\n        self.width = width\n        self.height = height\n    def accept(self, visitor):\n        return visitor.visit_rectangle(self)\n\nclass Triangle(Shape):\n    def __init__(self, base, height):\n        self.base = base\n        self.height = height\n    def accept(self, visitor):\n        return visitor.visit_triangle(self)\n\nclass AreaVisitor:\n    def visit_circle(self, c):\n        import math\n        return round(math.pi * c.radius ** 2, 2)\n    def visit_rectangle(self, r):\n        return r.width * r.height\n    def visit_triangle(self, t):\n        return 0.5 * t.base * t.height\n\nclass PerimeterVisitor:\n    def visit_circle(self, c):\n        import math\n        return round(2 * math.pi * c.radius, 2)\n    def visit_rectangle(self, r):\n        return 2 * (r.width + r.height)\n    def visit_triangle(self, t):\n        import math\n        side = math.sqrt((t.base/2)**2 + t.height**2)\n        return round(t.base + 2 * side, 2)\n\nshapes = [Circle(5), Rectangle(4, 6), Triangle(3, 4)]\narea_v = AreaVisitor()\nperim_v = PerimeterVisitor()\n\nfor shape in shapes:\n    print(f\"{shape.__class__.__name__}: area={shape.accept(area_v)}, perimeter={shape.accept(perim_v)}\")",
