     "code": "import copy\n\nclass Memento:\n    def __init__(self, state):\n        self._state = copy.deepcopy(state)\n    \n    @property\n    def state(self):\n        return copy.deepcopy(self._state)\n\nclass Document:\n    def __init__(self):\n        self.content = \"\"\n        self.font_size = 12\n    \n    def write(self, text):\n        self.content += text\n    \n    def set_font(self, size):\n        self.font_size = size\n    \n    def save(self):\n        return Memento({\"content\": self.content, \"font_size\": self.font_size})\n    \n    def restore(self, memento):\n        state = memento.state\n        self.content = state[\"content\"]\n        self.font_size = state[\"font_size\"]\n    \n    def __str__(self):\n        return f\"[{self.font_size}pt] {self.content}\"\n\nclass History:\n    def __init__(self):\n        self.undos = []\n        self.redos = []\n    \n    def save(self, memento):\n        self.undos.append(memento)\n        self.redos.clear()\n    \n    def undo(self):\n        if self.undos:\n            m = self.undos.pop()\n            self.redos.append(m)\n            return m\n    \n    def redo(self):\n        if self.redos:\n            m = self.redos.pop()\n            self.undos.append(m)\n            return m\n\ndoc = Document()\nhistory = History()\n\nhistory.save(doc.save()); doc.write(\"Hello \"); print(doc)\nhistory.save(doc.save()); doc.write(\"World\"); print(doc)\nhistory.save(doc.save()); doc.set_font(16); print(doc)\n\ndoc.restore(history.undo()); print(f\"Undo: {doc}\")\ndoc.restore(history.undo()); print(f\"Undo: {doc}\")",
