     "code": "class Event:\n    def __init__(self, type, data):\n        self.type = type\n        self.data = data\n\nclass WriteModel:\n    def __init__(self):\n        self.events = []\n    \n    def create_user(self, name, email):\n        event = Event(\"user_created\", {\"name\": name, \"email\": email})\n        self.events.append(event)\n        return event\n    \n    def update_user(self, user_id, **updates):\n        event = Event(\"user_updated\", {\"user_id\": user_id, **updates})\n        self.events.append(event)\n        return event\n\nclass ReadModel:\n    def __init__(self):\n        self.users = {}\n        self.next_id = 1\n    \n    def apply(self, event):\n        if event.type == \"user_created\":\n            self.users[self.next_id] = event.data\n            self.next_id += 1\n        elif event.type == \"user_updated\":\n            uid = event.data.pop(\"user_id\")\n            if uid in self.users:\n                self.users[uid].update(event.data)\n    \n    def get_user(self, user_id):\n        return self.users.get(user_id)\n    \n    def list_users(self):\n        return list(self.users.values())\n\nwrite = WriteModel()\nread = ReadModel()\n\n# Commands (writes)\ne1 = write.create_user(\"Alice\", \"alice@test.com\")\ne2 = write.create_user(\"Bob\", \"bob@test.com\")\ne3 = write.update_user(1, name=\"Alice Smith\")\n\n# Apply events to read model\nfor event in write.events:\n    read.apply(event)\n\n# Queries (reads)\nprint(read.list_users())\nprint(read.get_user(1))",
